#!/usr/bin/env bash
set +x
set -euo pipefail
umask 077
DEMO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
DEMO_ENV_FILE=${DEMO_ENV_FILE:-$DEMO_ROOT/.env}
LUMEN_STATE_DIR=${LUMEN_STATE_DIR:-${XDG_STATE_HOME:-$HOME/.local/state}/lumen-vault-demo}
export DEMO_ROOT DEMO_ENV_FILE LUMEN_STATE_DIR
fail() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }
load_inputs() {
  [ -f "$DEMO_ENV_FILE" ] || fail "Falta $DEMO_ENV_FILE. Copia .env.example y completa los secretos."
  set -a
  source "$DEMO_ENV_FILE"
  set +a
  # Vault connection/authentication is generated by vault.sh after init/unseal.
  # Ignore legacy .env entries and ambient CLI credentials during preflight.
  unset VAULT_TOKEN VAULT_ADDR VAULT_CACERT VAULT_NAMESPACE
  [ -n "${VERIFY_TENANT:-}" ] || fail 'Completa VERIFY_TENANT en .env.'
  export VERIFY_TENANT=${VERIFY_TENANT%/}
  export VAULT_ENV_FILE="$LUMEN_STATE_DIR/vault/config.env"
  mkdir -p "$LUMEN_STATE_DIR" "$LUMEN_STATE_DIR/logs" "$LUMEN_STATE_DIR/pids" "$LUMEN_STATE_DIR/vault"
  chmod 700 "$LUMEN_STATE_DIR" "$LUMEN_STATE_DIR/logs" "$LUMEN_STATE_DIR/pids" "$LUMEN_STATE_DIR/vault"
  chmod 600 "$DEMO_ENV_FILE"
}
load_vault() {
  [ -f "$VAULT_ENV_FILE" ] || fail 'Falta el bootstrap de Vault. Ejecuta ./demo.sh.'
  source "$VAULT_ENV_FILE"
  export VAULT_ADDR VAULT_TOKEN VAULT_CACERT
  export VAULT_NAMESPACE=''
}
K=(kubectl --context workshop)
port_pid() { lsof -nP -t -iTCP:"$1" -sTCP:LISTEN 2>/dev/null | sort -u; }
unload_managed() {
  local fingerprint
  fingerprint=$(printf '%s' "$LUMEN_STATE_DIR" | openssl dgst -sha256 | awk '{print substr($NF,1,12)}')
  launchctl bootout "gui/$(id -u)/local.lumen-demo.$fingerprint.$1" >/dev/null 2>&1 || true
}
start_managed() {
  local name=$1; shift
  [ "$(uname -s)" = Darwin ] || fail 'El supervisor de procesos de esta demo requiere macOS/launchd.'
  local label fingerprint file
  fingerprint=$(printf '%s' "$LUMEN_STATE_DIR" | openssl dgst -sha256 | awk '{print substr($NF,1,12)}')
  label="local.lumen-demo.$fingerprint.$name"
  mkdir -p "$LUMEN_STATE_DIR/services"
  file="$LUMEN_STATE_DIR/services/$name.plist"
  jq -n --arg label "$label" --arg state "$LUMEN_STATE_DIR" --arg path "$PATH" --arg userhome "$HOME" --arg name "$name" --arg verify "${CHATBOT_VERIFY_ACCESS:-0}" --arg tenant "$VERIFY_TENANT" --arg raw "${LUMEN_TRACE_VAULT_RAW:-1}" --arg content "${LUMEN_TRACE_CONTENT:-1}" --args \
    '{Label:$label,ProgramArguments:$ARGS.positional,WorkingDirectory:$state,RunAtLoad:true,KeepAlive:($name != "lumen"),ThrottleInterval:10,EnvironmentVariables:{PATH:$path,HOME:$userhome,VAULT_ENV_FILE:($state+"/vault/config.env"),LUMEN_STATE_DIR:$state,VERIFY_TENANT:$tenant,LUMEN_TRACE_VAULT_RAW:$raw,LUMEN_TRACE_CONTENT:$content,CHATBOT_VERIFY_ACCESS:$verify},StandardOutPath:($state+"/logs/"+$name+".log"),StandardErrorPath:($state+"/logs/"+$name+".log")}' -- "$@" > "$file"
  plutil -convert xml1 "$file"
  unload_managed "$name"
  launchctl bootstrap "gui/$(id -u)" "$file"
}
start_forward() {
  local name=$1 ns=$2 target=$3 port=$4 remote=$5 pid command
  pid=$(port_pid "$port" || true)
  if [ -n "$pid" ]; then
    [[ "$pid" =~ ^[0-9]+$ ]] || fail "Puerto $port tiene varios procesos escuchando; no se detienen automáticamente."
    command=$(ps -p "$pid" -o command=)
    [[ "$command" == *kubectl*"--context workshop "* && "$command" == *" -n $ns "* && "$command" == *"port-forward "*"$target "*"$port:$remote"* ]] || fail "Puerto $port ocupado por otro proceso; no se detiene automáticamente."
    # A listening kubectl can still point at a deleted pod, and an unmanaged
    # forward may disappear when its parent exits. Rebind it under launchd.
    printf 'Renovando port-forward %s\n' "$name"
    # Unload before signalling: KeepAlive must not race the replacement.
    unload_managed "$name"
    kill "$pid" 2>/dev/null || true
    for attempt in $(seq 1 30); do
      [ -n "$(port_pid "$port" || true)" ] || break
      sleep 1
    done
    [ -z "$(port_pid "$port" || true)" ] || fail "El port-forward anterior de $name no se ha detenido."
  fi
  start_managed "$name" "$(command -v kubectl)" --context workshop -n "$ns" port-forward --address 127.0.0.1 "$target" "$port:$remote"
  for attempt in $(seq 1 30); do
    pid=$(port_pid "$port" || true)
    if [ -n "$pid" ]; then printf '%s\n' "$pid" > "$LUMEN_STATE_DIR/pids/$name.pid"; return; fi
    sleep 1
  done
  fail "Timeout del port-forward $name"
}
wait_http() {
  local url=$1
  for attempt in $(seq 1 60); do
    if curl -fsS --max-time 3 "$url" >/dev/null 2>&1; then return; fi
    sleep 1
  done
  fail "No responde $url"
}
